import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();

        // Replace only the first 'at' with '@'
        line = line.replaceFirst("at", "@");
        // Replace all 'dot' with '.'
        line = line.replace("dot", ".");

        // If string starts with '.', prepend 'dot'
        if (line.startsWith(".")) {
            line = "dot" + line.substring(1);
        }

        // If string starts with '@', replace first 'at' with '@' and prepend 'at'
        if (line.startsWith("@")) {
            line = line.replaceFirst("at", "@");
            line = "at" + line.substring(1);
        }

        // If string ends with '.', replace with 'dot'
        if (line.endsWith(".")) {
            line = line.substring(0, line.length() - 1) + "dot";
        }

        System.out.println(line);
        scanner.close();
    }
}
